// ====== CẤU HÌNH – sửa ở đây ======
// Token Threads và key Gemini KHÔNG để ở đây: chúng nằm trong Credentials của n8n.
const SITE_URL = 'https://toeicmastery.click';

// Kiểu bài, chọn ngẫu nhiên mỗi lần chạy để feed không bị lặp.
const ANGLES = [
  'Mẹo nhanh: 1 mẹo làm bài cụ thể, áp dụng được ngay',
  'Lỗi sai hay gặp: chỉ ra 1 lỗi người học hay mắc và cách sửa',
  'Mini quiz: 1 câu hỏi kiểu TOEIC Part 5 (4 đáp án A-D), đáp án và giải thích ngắn ở cuối bài',
  '3 từ vựng: 3 từ/cụm từ hay gặp trong TOEIC, mỗi từ có nghĩa và 1 câu ví dụ ngắn',
];

// Tên thương hiệu khác: bài nào nhắc tới sẽ KHÔNG được đăng. Thêm tên vào đây khi cần.
const BLOCKED_BRANDS = [
  // Không chặn "prep" đứng riêng: đó cũng là viết tắt của preposition và khung trả lời PREP.
  'study4', 'prep\\.vn', 'dethitoeic', 'hochay', 'toeichanquoc', 'toeic hàn quốc', 'english mastery',
  'mshoa', 'ms hoa', '\\bzim\\b', 'ielts fighter', 'tienganh123', 'elsa speak', 'duolingo',
  'toeicmastery\\.vn',
];

// Trang KHÔNG đem đi quảng bá: đường dẫn chứa một trong các chữ này (web không dạy các kỹ năng/kỳ thi đó).
const SKIP_PATHS = ['speaking', 'writing', 'ielts', 'toefl', 'english-mastery'];

return [{
  json: {
    SITE_URL,
    angle: ANGLES[Math.floor(Math.random() * ANGLES.length)],
    BLOCKED_BRANDS,
    SKIP_PATHS,
    timestamp: new Date().toISOString(),
  },
}];

// Chọn 1 trang công khai của chính TOEIC Mastery từ sitemap.
// Chỉ lấy trang khách chưa đăng nhập xem được: hướng dẫn, từ vựng, blog, thi thử miễn phí.
const init = $('⚙️ Cấu hình').first().json;
const xml = String($input.first().json.data || '');
const urls = [...xml.matchAll(/<loc>\s*([^<\s]+)\s*<\/loc>/g)].map((m) => m[1]);

const CONTENT = /^\/(thi-thu-mien-phi$|(huong-dan|tu-vung|blog)\/[^/]+$)/;
const candidates = urls.filter((u) => {
  // Không dùng new URL(): sandbox Code node của n8n không có URL.
  const path = u.replace(/^https?:\/\/[^/]+/, '').split(/[?#]/)[0];
  return CONTENT.test(path) && !init.SKIP_PATHS.some((s) => path.toLowerCase().includes(s));
});
if (candidates.length === 0) {
  throw new Error('Sitemap không có trang nội dung nào – kiểm tra ' + init.SITE_URL + '/sitemap.xml');
}

// Tránh đăng lại trang vừa dùng gần đây (lưu ở static data, chỉ có tác dụng khi workflow chạy theo lịch).
const store = $getWorkflowStaticData('global');
const recent = store.recentUrls || [];
const fresh = candidates.filter((u) => !recent.includes(u));
const pool = fresh.length > 0 ? fresh : candidates;
const pageUrl = pool[Math.floor(Math.random() * pool.length)];

return [{ json: { ...init, pageUrl } }];

const prev = $('🎯 Chọn trang để quảng bá').first().json;
const html = String($input.first().json.data || '');

const decode = (s) => s
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"')
  .replace(/&#x27;|&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>');

const titleMatch = html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i) || html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
const pageTitle = decode((titleMatch ? titleMatch[1] : '').replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();

// Chỉ lấy phần nội dung chính, bỏ menu/header/footer.
const mainMatch = html.match(/<main[\s\S]*?<\/main>/i) || html.match(/<article[\s\S]*?<\/article>/i);
const pageText = decode(String(mainMatch ? mainMatch[0] : html)
  .replace(/<(script|style|nav|header|footer|svg)[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<[^>]+>/g, ' '))
  .replace(/\s+/g, ' ')
  .trim()
  .substring(0, 3500);

if (pageText.length < 200) {
  throw new Error('Không đọc được nội dung trang ' + prev.pageUrl + ' (quá ngắn) – không đăng bài.');
}

const prompt = [
  'Bạn viết bài cho tài khoản Threads chính thức của TOEIC Mastery (toeicmastery.click) – nền tảng luyện thi TOEIC Listening & Reading online: đề thi thử sát thực tế, từ vựng theo lộ trình, AI Mentor và phân tích điểm yếu theo từng Part.',
  '',
  'NHIỆM VỤ: viết 1 bài Threads bằng tiếng Việt, dựa trên trang "' + pageTitle + '" của TOEIC Mastery.',
  'Kiểu bài: ' + prev.angle,
  '',
  'NỘI DUNG TRANG (nguồn duy nhất được dùng):',
  '"""',
  pageText,
  '"""',
  '',
  'QUY TẮC BẮT BUỘC:',
  '1. Chỉ dùng thông tin có trong NỘI DUNG TRANG và kiến thức chuẩn về đề TOEIC (200 câu, 120 phút, Listening Part 1-4, Reading Part 5-7, thang điểm 10-990). Không bịa số liệu, tỉ lệ, cam kết tăng điểm hay ưu đãi.',
  '2. Không nhắc tên bất kỳ website, ứng dụng, trung tâm hay thương hiệu nào khác. Thương hiệu duy nhất được nhắc là TOEIC Mastery.',
  '3. Không xưng "tôi" kể kinh nghiệm cá nhân, không bịa câu chuyện học viên.',
  '3b. Không nói "không cần đăng nhập": muốn học trên web phải đăng ký tài khoản.',
  '4. Câu tiếng Anh phải đúng ngữ pháp và đúng nghĩa.',
  '5. Tối đa 450 ký tự, kể cả link và hashtag. Không dùng markdown (không **, không #tiêu đề).',
  '6. Câu đầu là hook ngắn, cụ thể. Thân bài 2-4 dòng ngắn, có thể dùng emoji 📌✅💡🎯.',
  '7. Dòng áp chót đúng nguyên văn: 👉 Xem chi tiết: ' + prev.pageUrl,
  '8. Dòng cuối 2-3 hashtag, trong đó có #TOEIC và #TOEICMastery.',
  '9. Không thêm link nào khác.',
  '',
  'Chỉ trả về nội dung bài viết.',
].join('\n');

return [{ json: { ...prev, pageTitle, prompt } }];

// Kiểm tra bài trước khi đăng. Bài không đạt -> báo lỗi và DỪNG, không đăng gì.
const prev = $('🧹 Đọc trang & tạo prompt').first().json;
const resp = $input.first().json;

let post = (resp.candidates?.[0]?.content?.parts || []).map((p) => p.text || '').join('').trim();
post = post.replace(/\*\*/g, '').replace(/^["“]|["”]$/g, '').trim();

const problems = [];
if (!post) problems.push('AI không trả về nội dung (finishReason: ' + (resp.candidates?.[0]?.finishReason || 'n/a') + ')');
if (post.length > 500) problems.push('Dài ' + post.length + ' ký tự (Threads giới hạn 500)');
if (!post.includes(prev.pageUrl)) problems.push('Thiếu link đúng của trang: ' + prev.pageUrl);

const lower = post.toLowerCase();
for (const brand of prev.BLOCKED_BRANDS) {
  if (new RegExp(brand, 'i').test(lower)) problems.push('Nhắc thương hiệu bị chặn: ' + brand);
}
// Mọi domain khác ngoài toeicmastery.click đều không được phép.
const domains = lower.match(/\b[a-z0-9-]+(\.[a-z0-9-]+)*\.(vn|com|net|org|edu|io|app|click|me|co)\b/g) || [];
for (const d of domains) {
  if (!/(^|\.)toeicmastery\.click$/.test(d)) problems.push('Có domain lạ: ' + d);
}

if (/không cần (đăng nhập|đăng ký|tài khoản)/.test(lower)) problems.push('Nói "không cần đăng nhập" – web phải đăng nhập');
if (problems.length > 0) {
  throw new Error('Bài KHÔNG được đăng:\n- ' + problems.join('\n- ') + '\n\nNội dung AI viết:\n' + post);
}

return [{ json: { ...prev, generatedContent: post } }];

const prev = $('✅ Kiểm tra bài trước khi đăng').first().json;
const pub = $input.first().json;

// Ghi nhớ trang vừa đăng để lần sau không lặp (giữ 30 trang gần nhất).
const store = $getWorkflowStaticData('global');
store.recentUrls = [prev.pageUrl, ...(store.recentUrls || []).filter((u) => u !== prev.pageUrl)].slice(0, 30);

return [{
  json: {
    status: 'ĐÃ ĐĂNG LÊN THREADS',
    thoiGian: new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' }),
    trang: prev.pageTitle,
    link: prev.pageUrl,
    kieuBai: prev.angle,
    noiDung: prev.generatedContent,
    threadsPostId: pub?.id || null,
  },
}];
